              </Flex>
              {!last && (
                <Box
                  flex="1"
                  h="2px"
                  minW="4"
                  rounded="full"
                  bg={done ? "blue.solid" : "border"}
                  aria-hidden="true"
                />
              )}
            </Flex>
          )
        })}
      </Flex>
    </Box>
  )
}
