} from "@/lib/data"
import { isEmail } from "@/lib/validation"

interface SummaryCardProps {
  data: OnboardingData
}

function Row({
  label,
  children,
}: {
  label: string
  children: React.ReactNode
}) {
  return (
    <Box>
      <Text as="dt" textStyle="xs" color="fg.muted" textTransform="uppercase" letterSpacing="wider">
