                          {item.description}
                        </Span>
                      </Checkbox.Label>
                    </Checkbox.Root>
                  </li>
                )
              })}
            </Stack>
          </Card.Body>
          <Card.Footer>
            <Button asChild variant="ghost" size="sm">
