                  color={active ? "fg" : "fg.muted"}
                  display={{ base: "none", md: "inline" }}
                  aria-hidden="true"
                >
                  {step.short}
                </Span>
                <Span srOnly>
                  {done ? "Completed: " : active ? "Current step: " : "Upcoming: "}
                  {step.short}
                  {` (step ${index + 1} of ${steps.length})`}
                </Span>
              </Flex>
              {!last && (
                <Box
                  flex="1"
                  h="2px"
                  minW="4"
                  rounded="full"
                  bg={done ? "blue.solid" : "border"}
                  aria-hidden="true"
                />
              )}
            </Flex>
          )
        })}
      </Flex>
    </Box>
  )
}
